use desafio::soma_de_dois_em_dois;

#[test]
fn testa_a_soma_de_dois_em_dois_ate_dez() {
    assert_eq!(soma_de_dois_em_dois(10), 20);
}

#[test]
fn testa_a_soma_de_dois_em_dois_ate_cinco() {
    assert_eq!(soma_de_dois_em_dois(5), 6);
}

#[test]
fn testa_o_intervalo_de_um_so_restara_o_zero() {
    assert_eq!(soma_de_dois_em_dois(1), 0);
}
